const axios = require('axios')
const fs = require('fs').promises

/*********************************************************
 *
 * SETUP:
 *
 * Create a new directory e.g. code-samples
 * Copy this whole file and save to code-samples/threat_removal_instant.js
 * Copy 'USAGE:' code to code-samples/instant.js
 * Update code-samples/instant.js with your API KEY and paths for input and output
 * > cd code-samples
 * > npm install axios
 * > node instant.js
 *
 * USAGE:
 *
 * const threat_removal_instant = require('./threat_removal_instant')
 * threat_removal_instant.start('${URL}',
 *     'ABC----YOUR_APIKEY----789',
 *     'input.doc',
 *     'output.docx',
 *     'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
 *     false,
 *     'application/msword')
 * .then(({filename, responseHeaders}) => {
 *     console.log(`Success: ${filename}`)
 *     console.log(responseHeaders)
 * })
 * .catch(err => {
 *     if (!err.response || !err.response.data) {
 *         console.error(err.message)
 *     } else console.error('Response data:', err.response.data);
 * });
 *
 ********************************************************/

exports.start = async (apiEndpointBase, apiKey, inputFilename, targetFilename, mimeType, convertFrom) => {

    const uploadResponse = await upload(apiEndpointBase, apiKey, inputFilename, mimeType, convertFrom)

    await fs.writeFile(targetFilename, uploadResponse.data)

    const responseHeaders = Object.keys(uploadResponse.headers)
        .filter(headerName => headerName.startsWith('content') || headerName.startsWith('x-'))
        .reduce((headers, headerName) => {
            headers[headerName] = uploadResponse.headers[headerName]
            return headers
        }, {})

    return { filename: targetFilename, responseHeaders }
}

async function upload(apiEndpointBase, apiKey, inputFilename, mimeType, convertFrom) {
    try {
        const data = await fs.readFile(inputFilename)
        headers =  {
            'Accept': [mimeType, 'application/json'].join(', '),
            'Content-Type': mimeType,
            'x-api-key': apiKey
        }
        if (convertFrom) headers['X-Options'] = JSON.stringify({ conversion: { from: { "mime-type": convertFrom }}})
        const response = await axios({
            method: 'POST', headers,
            responseType: 'arraybuffer',
            url: apiEndpointBase + '/upload',
            maxContentLength: Math.max(20000, data.length * 2), // output could be larger than input
            data: data
        })

        return response
    }
    catch (err) {
        if (err.response && err.response.data) err.response.data = JSON.parse(err.response.data)
        throw err
    }
}
